const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const jsonString = buffer.toString('utf-8');
const parsed = JSON.parse(jsonString);
const imageUrls = parsed.image;

// yyyyMMdd-HH 형식 디렉토리명 생성
const kst = new Date(new Date().getTime() + 9 * 60 * 60 * 1000);
const dirName = kst.toISOString().replace(/[-T:]/g, '').slice(0, 8) + '-' + kst.toISOString().slice(11, 13);

const results = [];
for (let i = 0; i < imageUrls.length; i++) {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: imageUrls[i],
    encoding: 'arraybuffer',
    returnFullResponse: true,
  });

  const fileName = `image_${i + 1}.jpg`;
  results.push({
    json: { fileName, dirName, url: imageUrls[i], status: 'downloaded' },
    binary: {
      data: await this.helpers.prepareBinaryData(
        Buffer.from(response.body),
        fileName,
        'image/jpeg'
      ),
    },
  });
}

return results;

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const jsonString = buffer.toString('utf-8');
const parsed = JSON.parse(jsonString);

const kst = new Date(new Date().getTime() + 9 * 60 * 60 * 1000);
const dirName = kst.toISOString().replace(/[-T:]/g, '').slice(0, 8) + '-' + kst.toISOString().slice(11, 13);

return [{
  json: {
    title: parsed.title,
    text: parsed.text,
    dirName
  }
}];

const content = $input.first().json.message.content;
const subtitles = JSON.parse(content);

const kst = new Date(new Date().getTime() + 9 * 60 * 60 * 1000);
const dirName = kst.toISOString().replace(/[-T:]/g, '').slice(0, 8) + '-' + kst.toISOString().slice(11, 13);

let srt = '';
for (let i = 0; i < subtitles.length; i++) {
  const start = i * 3;
  const end = start + 3;
  const startTime = `00:00:0${start},000`;
  const endTime = `00:00:0${end},000`;
  srt += `${i + 1}\n${startTime} --> ${endTime}\n${subtitles[i]}\n\n`;
}

return [{
  json: { fileName: 'subtitles.srt', dirName },
  binary: {
    data: await this.helpers.prepareBinaryData(
      Buffer.from(srt, 'utf-8'),
      'subtitles.srt',
      'text/plain'
    ),
  },
}];
